const photoUrlCache = new Map<string, string>();
function useFileUrl(path?: string | null): string {
  const [url, setUrl] = useState(path && (path.startsWith("http") || path.startsWith("blob") || path.startsWith("file")) ? path : "");
  useEffect(() => {
    let live = true;
    if (path && !url) {
      const cached = photoUrlCache.get(path);
      if (cached) { setUrl(cached); return; }
      uploadService.fileUrl(path).then((u) => { photoUrlCache.set(path, u); if (live) setUrl(u); }).catch(() => {});
    }
    return () => { live = false; };
  }, [path]);
  return url;
}

function PhotoView({ path, style }: { path?: string | null; style?: any }) {
  const url = useFileUrl(path);
  return <View style={style}>{url ? <ExpoImage source={{ uri: url }} style={{ width: "100%", height: "100%" }} contentFit="cover" /> : <View style={{ flex: 1, alignItems: "center", justifyContent: "center" }}><Icon name="image-outline" color="#8AA0B5" /></View>}</View>;
}

async function pickJobPhoto(source: "camera" | "gallery"): Promise<ImagePicker.ImagePickerAsset | null> {
  const current = source === "camera" ? await ImagePicker.getCameraPermissionsAsync() : await ImagePicker.getMediaLibraryPermissionsAsync();
  let granted = current.granted; let canAsk = current.canAskAgain;
  if (!granted && canAsk) {
    const result = source === "camera" ? await ImagePicker.requestCameraPermissionsAsync() : await ImagePicker.requestMediaLibraryPermissionsAsync();
    granted = result.granted; canAsk = result.canAskAgain;
  }
  if (!granted) {
    Alert.alert("Permission needed", "ShedX uses photos as proof of work for customers.", canAsk ? [{ text: "OK" }] : [{ text: "Cancel" }, { text: "Open Settings", onPress: () => Linking.openSettings() }]);
    return null;
  }
  const result = source === "camera" ? await ImagePicker.launchCameraAsync({ quality: 0.6 }) : await ImagePicker.launchImageLibraryAsync({ mediaTypes: ["images"], quality: 0.6 });
  return result.canceled ? null : result.assets[0];
}

